using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly FakeProvider provider = new();

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint_with_reference_amount_and_currency()
    {
        provider.Respond(200, """{"status":"approved"}""");

        await Gateway().AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        var sent = Assert.Single(provider.Requests);
        Assert.Equal("POST", sent.Method);
        Assert.Equal("/v1/authorizations", sent.Path);
        Assert.StartsWith("application/json", sent.ContentType);
        using var json = JsonDocument.Parse(sent.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        provider.Respond(200, """{"status":"approved"}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-1", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        provider.Respond(200, """{"status":"declined"}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-2", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Unknown_extra_fields_in_the_answer_are_ignored()
    {
        provider.Respond(200, """{"id":"auth_1","status":"approved","risk":{"score":3}}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-3", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Theory]
    [InlineData("""{}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("""null""")]
    public async Task An_answer_that_does_not_clearly_say_approved_is_never_treated_as_approved(string body)
    {
        provider.Respond(200, body);

        var outcome = await Gateway().AuthorizeAsync("ORD-4", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_refusal_is_read_as_declined()
    {
        provider.Respond(402, """{"error":"card_refused"}""");

        var outcome = await Gateway().AuthorizeAsync("ORD-5", new Money(5, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_a_decision(int status)
    {
        provider.Respond(status, """{"error":"nope"}""");

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            Gateway().AuthorizeAsync("ORD-6", new Money(5, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_success_answer_that_is_not_json_surfaces_as_an_error()
    {
        provider.Respond(200, "<html>oops</html>");

        await Assert.ThrowsAnyAsync<JsonException>(() =>
            Gateway().AuthorizeAsync("ORD-8", new Money(5, "EUR"), CancellationToken.None));
    }

    private HttpPaymentGateway Gateway() => new(new HttpClient { BaseAddress = provider.BaseAddress });

    public void Dispose() => provider.Dispose();

    private sealed record ReceivedRequest(string Method, string Path, string? ContentType, string Body);

    private sealed class FakeProvider : IDisposable
    {
        private readonly HttpListener listener = new();
        private readonly List<ReceivedRequest> requests = [];
        private int status = 200;
        private string body = "";

        public FakeProvider()
        {
            var probe = new TcpListener(IPAddress.Loopback, 0);
            probe.Start();
            var port = ((IPEndPoint)probe.LocalEndpoint).Port;
            probe.Stop();

            BaseAddress = new Uri($"http://127.0.0.1:{port}/");
            listener.Prefixes.Add(BaseAddress.ToString());
            listener.Start();
            _ = Task.Run(Serve);
        }

        public Uri BaseAddress { get; }

        public IReadOnlyList<ReceivedRequest> Requests { get { lock (requests) return [.. requests]; } }

        public void Respond(int statusCode, string responseBody) => (status, body) = (statusCode, responseBody);

        private async Task Serve()
        {
            while (listener.IsListening)
            {
                HttpListenerContext context;
                try { context = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
                var received = new ReceivedRequest(
                    context.Request.HttpMethod,
                    context.Request.Url!.AbsolutePath,
                    context.Request.ContentType,
                    await reader.ReadToEndAsync());
                lock (requests) requests.Add(received);

                var bytes = Encoding.UTF8.GetBytes(body);
                context.Response.StatusCode = status;
                context.Response.ContentType = "application/json";
                await context.Response.OutputStream.WriteAsync(bytes);
                context.Response.Close();
            }
        }

        public void Dispose() => listener.Close();
    }
}
